<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence;
use App\Application\Read\Page;
final class PdoReportRepository extends PdoRepository
{
    private function query(string $sql,array $params=[]):array{$s=$this->pdo()->prepare($sql);$s->execute($params);return$s->fetchAll();}
    private function scope(string $column,?array $allowed,array &$params):string{if($allowed===null)return'';if($allowed===[])return' AND 1=0';foreach($allowed as$id)$params[]=(int)$id;return' AND '.$column.' IN('.implode(',',array_fill(0,count($allowed),'?')).')';}
    private function base(array$f,string$branch,string$date,?array$allowed,array&$p):string{$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=" WHERE $date BETWEEN ? AND ?".$this->scope($branch,$allowed,$p);if($f['branch']!==null){$w.=" AND $branch=?";$p[]=$f['branch'];}return$w;}
    public function report(array$f,?array$allowed,int$limit=25,int$offset=0):array
    {
        if($limit<1||$limit>\App\Application\Reporting\ReportExportPolicy::MAX_ROWS||$offset<0)throw new \InvalidArgumentException('Límites de reporte inválidos.');
        return match($f['type']){'quotes'=>$this->quotes($f,$allowed,$limit,$offset),'inventory'=>$this->inventory($f,$allowed,$limit,$offset),'purchases'=>$this->purchases($f,$allowed,$limit,$offset),'transfers'=>$this->transfers($f,$allowed,$limit,$offset),'deliveries'=>$this->deliveries($f,$allowed,$limit,$offset),default=>throw new \InvalidArgumentException('Reporte inválido.')};
    }
    private function page(array$rows,int$limit,int$offset):Page{$more=count($rows)>$limit;if($more)array_pop($rows);return new Page($rows,$limit,$offset,$more);}
    private function quotes(array$f,?array$a,int$l,int$o):array
    {
        $p=[];$w=$this->base($f,'q.branch_id','q.created_at',$a,$p);
        if($f['status']!==''){$w.=' AND q.status=?';$p[]=$f['status'];}if($f['origin']!==''){$w.=' AND COALESCE(w.origin,\'internal\')=?';$p[]=$f['origin'];}if($f['q']!==''){$w.=' AND (q.folio LIKE ? OR c.legal_name LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}
        $join=' FROM quotes q JOIN customers c ON c.id=q.customer_id JOIN branches b ON b.id=q.branch_id JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version LEFT JOIN quote_workflows w ON w.quote_id=q.id';
        $summary=$this->query('SELECT COUNT(*) total,COALESCE(SUM(q.status=\'accepted\'),0) accepted,COALESCE(SUM(q.status=\'rejected\'),0) rejected,COALESCE(SUM(q.status=\'cancelled\'),0) cancelled,COALESCE(SUM(q.status IN(\'received\',\'assigned\',\'preparing\',\'pending_approval\',\'sent\')),0) pending,COALESCE(SUM(CASE WHEN q.status<>\'cancelled\' THEN v.total ELSE 0 END),0) estimated,ROUND(AVG(TIMESTAMPDIFF(MINUTE,q.created_at,(SELECT MIN(e.created_at) FROM quote_workflow_events e WHERE e.workflow_id=w.id AND e.action IN(\'take\',\'contact\',\'prepare\')))),1) first_attention_minutes,MAX(CASE WHEN q.status IN(\'received\',\'assigned\',\'preparing\',\'pending_approval\',\'sent\') THEN DATEDIFF(CURRENT_DATE,DATE(q.created_at)) ELSE 0 END) oldest_pending_days'.$join.$w,$p)[0];
        $series=$this->query('SELECT DATE(q.created_at) label,COUNT(*) value'.$join.$w.' GROUP BY DATE(q.created_at) ORDER BY label',$p);
        $states=$this->query('SELECT q.status label,COUNT(*) value'.$join.$w.' GROUP BY q.status ORDER BY value DESC,label',$p);
        $channels=$this->query("SELECT COALESCE(w.origin,'internal') label,COUNT(*) value".$join.$w.' GROUP BY COALESCE(w.origin,\'internal\') ORDER BY value DESC,label',$p);
        $branches=$this->query('SELECT b.name label,COUNT(*) value'.$join.$w.' GROUP BY b.id,b.name ORDER BY value DESC,label',$p);
        $rows=$this->query("SELECT q.id,q.folio,c.legal_name customer,b.name branch,q.status,COALESCE(w.origin,'internal') origin,v.total,DATE(q.created_at) created_date,DATEDIFF(CURRENT_DATE,DATE(q.created_at)) age_days".$join.$w.' ORDER BY q.created_at DESC,q.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);
        return['title'=>'Cotizaciones','summary'=>$summary,'series'=>$series,'states'=>$states,'channels'=>$channels,'branches'=>$branches,'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Cliente','Sucursal','Estado','Canal','Total estimado MXN','Fecha de creación','Antigüedad (días)'],'keys'=>['folio','customer','branch','status','origin','total','created_date','age_days'],'date_basis'=>'Fecha de creación de la cotización. Primera atención: primer evento operativo registrado. El total es valor estimado documental, no ingreso.'];
    }
    private function inventory(array$f,?array$a,int$l,int$o):array
    {
        $p=[];$w=' WHERE 1=1'.$this->scope('ib.branch_id',$a,$p);if($f['branch']!==null){$w.=' AND ib.branch_id=?';$p[]=$f['branch'];}if($f['status']==='low')$w.=' AND st.minimum_quantity IS NOT NULL AND ib.available_quantity<=st.minimum_quantity';if($f['q']!==''){$w.=' AND (p.name LIKE ? OR v.sku LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}
        $join=' FROM inventory_balances ib JOIN branches b ON b.id=ib.branch_id JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id JOIN units u ON u.id=v.unit_id LEFT JOIN stock_thresholds st ON st.branch_id=ib.branch_id AND st.variant_id=ib.variant_id';
        $s=$this->query('SELECT COUNT(*) total,COALESCE(SUM(ib.physical_quantity>0),0) physical,COALESCE(SUM(ib.reserved_quantity>0),0) reserved,COALESCE(SUM(ib.available_quantity>0),0) available,COALESCE(SUM(st.minimum_quantity IS NOT NULL AND ib.available_quantity<=st.minimum_quantity),0) low'.$join.$w,$p)[0];
        $rows=$this->query('SELECT v.sku,p.name product,v.name variant,b.name branch,u.symbol,ib.physical_quantity physical,ib.reserved_quantity reserved,ib.available_quantity available,st.minimum_quantity minimum'.$join.$w.' ORDER BY p.name,v.sku,b.name LIMIT '.($l+1).' OFFSET '.$o,$p);
        return['title'=>'Inventario','summary'=>$s,'series'=>[],'states'=>[],'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['SKU','Producto','Variante','Sucursal','Unidad','Existencia física','Apartado','Disponible','Mínimo'],'keys'=>['sku','product','variant','branch','symbol','physical','reserved','available','minimum'],'date_basis'=>'Saldo actual del inventario; disponible = físico − apartado. Los indicadores cuentan saldos por variante y sucursal; no suman piezas, metros o kilogramos incompatibles.'];
    }
    private function purchases(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'i.branch_id','i.document_date',$a,$p);if($f['status']!==''){$w.=' AND i.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (i.folio LIKE ? OR s.legal_name LIKE ?)';$t='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$t,$t);}$j=' FROM supplier_invoices i JOIN suppliers s ON s.id=i.supplier_id JOIN branches b ON b.id=i.branch_id';$sum=$this->query('SELECT COUNT(*) total,COALESCE(SUM(i.status=\'received\'),0) completed,COALESCE(SUM(i.status=\'partial\'),0) partial,COALESCE(SUM(CASE WHEN i.status<>\'cancelled\' THEN i.total ELSE 0 END),0) documented'.$j.$w,$p)[0];$states=$this->query('SELECT i.status label,COUNT(*) value'.$j.$w.' GROUP BY i.status ORDER BY value DESC',$p);$rows=$this->query('SELECT i.folio,s.legal_name supplier,b.name branch,i.document_date,i.status,i.currency,i.total'.$j.$w.' ORDER BY i.document_date DESC,i.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Compras','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Proveedor','Sucursal','Fecha documento','Estado','Moneda','Total documentado'],'keys'=>['folio','supplier','branch','document_date','status','currency','total'],'date_basis'=>'Fecha del documento del proveedor; importes documentados, no pagos.'];}
    private function transfers(array$f,?array$a,int$l,int$o):array
    {$p=[$f['from'].' 00:00:00',$f['to'].' 23:59:59.999999'];$w=' WHERE t.created_at BETWEEN ? AND ?';if($a!==null){if(!$a)$w.=' AND 1=0';else{foreach($a as$id){$p[]=$id;$p[]=$id;}$w.=' AND ('.implode(' OR ',array_fill(0,count($a),'t.source_branch_id=? OR t.destination_branch_id=?')).')';}}if($f['branch']!==null){$w.=' AND (t.source_branch_id=? OR t.destination_branch_id=?)';array_push($p,$f['branch'],$f['branch']);}if($f['status']!==''){$w.=' AND t.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (t.folio LIKE ? OR t.reason LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x);}$j=' FROM transfers t JOIN branches bs ON bs.id=t.source_branch_id JOIN branches bd ON bd.id=t.destination_branch_id';$states=$this->query('SELECT t.status label,COUNT(*) value'.$j.$w.' GROUP BY t.status ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states))];foreach($states as$r)$sum[$r['label']]=$r['value'];$rows=$this->query('SELECT t.folio,bs.name source,bd.name destination,t.status,t.reason,DATE(t.created_at) created_date'.$j.$w.' ORDER BY t.created_at DESC,t.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Transferencias','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Origen','Destino','Estado','Motivo','Fecha de solicitud'],'keys'=>['folio','source','destination','status','reason','created_date'],'date_basis'=>'Fecha de creación de la solicitud; el alcance incluye origen o destino autorizado.'];}
    private function deliveries(array$f,?array$a,int$l,int$o):array
    {$p=[];$w=$this->base($f,'d.branch_id','d.created_at',$a,$p);if($f['status']!==''){$w.=' AND d.status=?';$p[]=$f['status'];}if($f['q']!==''){$w.=' AND (d.folio LIKE ? OR c.legal_name LIKE ?)';$x='%'.addcslashes($f['q'],'%_\\').'%';array_push($p,$x,$x);}$j=' FROM deliveries d JOIN branches b ON b.id=d.branch_id JOIN customers c ON c.id=d.customer_id JOIN quote_versions v ON v.id=d.quote_version_id JOIN quotes q ON q.id=v.quote_id';$states=$this->query('SELECT d.status label,COUNT(*) value'.$j.$w.' GROUP BY d.status ORDER BY value DESC',$p);$sum=['total'=>array_sum(array_map(fn($r)=>(int)$r['value'],$states)),'pending'=>0,'completed'=>0,'incidents'=>0];foreach($states as$r){if($r['label']==='delivered')$sum['completed']=$r['value'];elseif($r['label']==='failed')$sum['incidents']=$r['value'];elseif($r['label']!=='cancelled')$sum['pending']+=(int)$r['value'];}$rows=$this->query('SELECT d.folio,q.folio quote,c.legal_name customer,b.name branch,d.mode,d.status,d.scheduled_date,d.delivery_cost'.$j.$w.' ORDER BY d.created_at DESC,d.id DESC LIMIT '.($l+1).' OFFSET '.$o,$p);return['title'=>'Entregas','summary'=>$sum,'series'=>[],'states'=>$states,'channels'=>[],'page'=>$this->page($rows,$l,$o),'columns'=>['Folio','Cotización','Cliente','Sucursal','Modalidad','Estado','Fecha programada','Costo entrega MXN'],'keys'=>['folio','quote','customer','branch','mode','status','scheduled_date','delivery_cost'],'date_basis'=>'Fecha de creación de la entrega; la fecha programada se muestra como atributo operativo.'];}
}
